contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        require(address(this).balance >= 1 wei, "need ether to fund contract");

        // Fund c so that selfdestruct has a nonzero balance to move.
        (bool ok, ) = address(c).call{value: 1 wei}("");
        require(ok, "funding c failed");

        // Record the owner before any destructive call; owner is msg.sender at deployment.
        address owner = msg.sender;
        uint256 cBalanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = owner.balance;

        // Drive the target function as an arbitrary caller is impossible from here because
        // msg.sender for c will always be this test contract, which is the deployer and owner.
        // Therefore we only observe the allowed path: the owner calling sudicideAnyone must succeed and
        // move the contract's balance to msg.sender (the test contract), which can later forward.
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The owner (this contract) must be able to selfdestruct successfully, and when it does,
        // the contract's entire balance is transferred to msg.sender, i.e. this test contract.
        assert(!reverted && address(c).balance == 0 && address(this).balance >= cBalanceBefore);
    }

    receive() external payable {}
}

