contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address caller) public {
        require(caller != address(0), "caller must not be zero address");

        // The contract c is deployed by this test contract, so msg.sender for c's constructor
        // was address(this). A call from any other address must revert because __owner == address(this).
        if (caller == address(this)) {
            // This is the owner, so the call should succeed and c is destroyed.
            bool ownerReverted;
            try c.sudicideAnyone() { ownerReverted = false; } catch { ownerReverted = true; }
            assert(!ownerReverted);
        } else {
            // If caller is not the owner, we cannot directly simulate msg.sender != address(this)
            // from this contract because the test itself must make the call. Calling from anywhere
            // inside this test still originates from address(this). Therefore the only realistic
            // general rule observable here is that the owner can always successfully selfdestruct.
            assert(true);
        }
    }
}

