contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint amount) public payable {
        require(address(this).balance >= amount);
        uint balBefore = address(this).balance;
        uint cBalBefore = address(c).balance;
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);
        bool reverted;
        if (caller == address(this)) {
            try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
            assert(!reverted);
        } else {
            (bool success, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
            reverted = !success;
            assert(reverted);
            assert(address(c).balance == cBalBefore + amount);
            assert(address(this).balance == balBefore - amount);
        }
    }
    receive() external payable {}
}

