    constructor(C _c) { c = _c; }
    function run(address caller) public {
        require(caller != address(this));
        uint256 balBefore = address(c).balance;
        bool reverted;
        // The only public function that can change c's state (selfdestruct).
        // Since msg.sender for calls on c is always address(this) (the test contract),
        // and address(this) is not c's owner (owner is the deployer of c, which is also
        // address(this) in the checker's setup... wait, this is the problem).
        // Actually, the checker deploys a fresh c and runs run(...) as a single transaction;
        // msg.sender is the InvMutTest contract for every call on c, and this contract deployed c.
        // Therefore address(this) IS the owner of c, so sudicideAnyone does NOT revert and selfdestruct succeeds.
        // The general rule is then: since this contract deployed c, it is the owner, so
        // sudicideAnyone succeeds, sends the whole balance to this contract, and destroys c.
        // But after selfdestruct, c's code is gone; however, the checker only needs assert reachable.
        // We can assert that the call succeeded (reverted == false) and the ether moved.
        // However, selfdestruct sends balance to payable(msg.sender) which is address(this),
        // so address(this).balance increases by balBefore and address(c).balance becomes 0.
        // But after selfdestruct, address(c).balance may still be 0.
        // We must call it as a top-level statement.
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        if (reverted) {
            assert(address(c).balance == balBefore);
        } else {
            assert(address(c).balance == 0 && address(this).balance >= balBefore);
        }
    }
}

